// cf#923 fixtures. REAL MP4 containers produced by ffmpeg/libx264, base64-encoded, NOT hand-built.
// A hand-built fixture would encode the same assumption the parser makes and could not falsify it.
//
//   fx25: 16x16, 25fps, 1s, 25 frames  (the rate infinitetalk actually delivers)
//   fx30: 16x16, 30fps, 1s, 30 frames  (the rate alibaba-wan actually delivers)
//
// Both rates are the two the production doors returned while the modules reported a hardcoded 24.
// Verified with ffprobe -count_frames before committing: 25/1,25 and 30/1,30.

export const FX_25FPS_B64 =
  "";

export const FX_30FPS_B64 =
  "";

export function fx(b64: string): Uint8Array {
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}
